  return `linear-gradient(135deg, ${start}, ${middle} 56%, ${end})`;
}

"use client";

import type { ProductEventName, ProductEventProduct } from "./events";

export function trackProductEvent(event: ProductEventName, product: ProductEventProduct, mode?: string) {
  const payload = { event, product, ...(mode ? { mode } : {}) };
  void fetch("/api/telemetry", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
    keepalive: true,
  }).catch(() => undefined);
}

export const PRODUCT_EVENTS = [
  "analysis_started",
  "analysis_completed",
  "story_viewed",
  "story_exported",
  "share_created",
  "share_opened",
  "make_yours_clicked",
  "checkout_started",
  "purchase_verified",
  "story_saved",
  "myyear_created",
  "pet_created",
  "pet_memory_added",
  "annual_recap_created",
  "ai_enrichment_started",
  "ai_enrichment_completed",
] as const;

export type ProductEventName = typeof PRODUCT_EVENTS[number];
export type ProductEventProduct = "threadtales" | "myyear" | "petlife" | "relationship" | "lifemap" | "babystory" | "homestory" | "familytree" | "founderworld" | "creatorworld";

export interface ProductEvent {
  event: ProductEventName;
  product: ProductEventProduct;
  mode?: string;
}

const EVENT_SET = new Set<string>(PRODUCT_EVENTS);
const ALLOWED_MODES = new Set(["friends","couple","siblings","family","group","birthday","anniversary","long-distance","graduation","year-together"]);

export function sanitizeProductEvent(value: unknown): ProductEvent {
  if (!value || typeof value !== "object") throw new Error("Invalid product event.");
  const input = value as Record<string, unknown>;
  if (typeof input.event !== "string" || !EVENT_SET.has(input.event)) throw new Error("Unsupported product event.");
  if (typeof input.product !== "string" || !["threadtales","myyear","petlife","relationship","lifemap","babystory","homestory","familytree","founderworld","creatorworld"].includes(input.product)) throw new Error("Unsupported event product.");
  const mode = typeof input.mode === "string" && ALLOWED_MODES.has(input.mode) ? input.mode : undefined;
  return { event: input.event as ProductEventName, product: input.product as ProductEventProduct, ...(mode ? { mode } : {}) };
}

import type { ProductEvent } from "./events";

const PROJECT = {
  organizationId: "portfolio_primary",
  projectId: "proj_friendship_wrapped",
  projectSlug: "friendship-wrapped",
} as const;

function environment() {
  const value = process.env.PULSEATLAS_ENVIRONMENT;
  return value === "development" || value === "preview" ? value : "production";
}

export function toPulseAtlasEvent(event: ProductEvent) {
  return {
    id: `evt_${crypto.randomUUID()}`,
    schemaVersion: 1,
    ...PROJECT,
    environment: environment(),
    eventName: event.event,
    eventCategory: event.event === "purchase_verified" ? "revenue" : event.event === "checkout_started" ? "conversion" : "product",
    occurredAt: new Date().toISOString(),
    properties: {
      product: event.product,
      ...(event.mode ? { mode: event.mode } : {}),
    },
  };
}

export async function deliverToPulseAtlas(event: ProductEvent): Promise<boolean> {
  const rawEndpoint = process.env.PULSEATLAS_ENDPOINT;
  const writeKey = process.env.PULSEATLAS_WRITE_KEY;
  if (!rawEndpoint || !writeKey) return false;

  try {
    const endpoint = new URL(rawEndpoint);
    const local = endpoint.hostname === "localhost" || endpoint.hostname === "127.0.0.1";
    if (endpoint.protocol !== "https:" && !local) return false;
    const response = await fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-pulseatlas-write-key": writeKey },
      body: JSON.stringify(toPulseAtlasEvent(event)),
      cache: "no-store",
      signal: AbortSignal.timeout(1500),
    });
    return response.ok;
  } catch {
    // Portfolio observability must never break the story product.
    return false;
  }
}

import type { ChatMessage } from "@/lib/types";

export interface RecurringPhraseCandidate {
  phrase: string;
  count: number;
}

export interface ThreadTalesLocalLore {
  firstMessageText?: string;
  recurringPhrases: RecurringPhraseCandidate[];
}

const STOP_PHRASE_WORDS = new Set([
  "the", "and", "that", "this", "with", "have", "just", "from", "your", "you", "are", "was", "were", "for", "but", "not", "what", "when", "how", "can", "will", "would", "could", "should", "they", "them", "then", "than", "its", "it's", "im", "i'm", "yeah", "yes", "okay", "ok",
]);

function words(text: string) {
  return text
    .normalize("NFKC")
    .replace(/https?:\/\/\S+/gi, " ")
    .replace(/<media omitted>|image omitted|video omitted|sticker omitted/gi, " ")
    .toLowerCase()
    .match(/[\p{L}\p{N}][\p{L}\p{N}'’_-]*/gu)?.slice(0, 80) ?? [];
}

function usefulPhrase(tokens: string[]) {
  if (tokens.length < 2) return false;
  if (tokens.every((token) => STOP_PHRASE_WORDS.has(token))) return false;
  return tokens.some((token) => token.length >= 4 && !STOP_PHRASE_WORDS.has(token));
}

export function extractRecurringPhraseCandidates(messages: ChatMessage[], limit = 8) {
  const counts = new Map<string, number>();
  for (const message of messages) {
    const tokens = words(message.text);
    const seen = new Set<string>();
    for (let size = 2; size <= 5; size += 1) {
      for (let start = 0; start + size <= tokens.length; start += 1) {
        const slice = tokens.slice(start, start + size);
        if (!usefulPhrase(slice)) continue;
        const phrase = slice.join(" ");
        if (phrase.length > 80 || seen.has(phrase)) continue;
        seen.add(phrase);
        counts.set(phrase, (counts.get(phrase) ?? 0) + 1);
      }
    }
  }
  return [...counts.entries()]
    .filter(([, count]) => count >= 3)
    .map(([phrase, count]) => ({ phrase, count }))
    .sort((a, b) => b.count - a.count || b.phrase.split(" ").length - a.phrase.split(" ").length || a.phrase.localeCompare(b.phrase))
    .slice(0, Math.max(0, Math.min(12, limit)));
}

export function buildThreadTalesLocalLore(messages: ChatMessage[]): ThreadTalesLocalLore {
  return {
    firstMessageText: messages[0]?.text.trim().slice(0, 240) || undefined,
    recurringPhrases: extractRecurringPhraseCandidates(messages),
  };
}

import type { ChatStats } from "@/lib/types";
