import type { StoryChapter, StoryEvent } from "@/platform/types";

export interface MyYearMoment {
  id: string;
  title: string;
  date: string;
  caption?: string;
  location?: string;
  photoCount: number;
}

export interface MyYearEra {
  id: string;
  label: string;
  startMonth: number;
  endMonth: number;
  moments: number;
}

export interface MyYearSummary {
  schemaVersion: 1;
  product: "myyear";
  year: number;
  title: string;
  moments: MyYearMoment[];
  monthlyCounts: Array<{ month: number; label: string; moments: number }>;
  eras: MyYearEra[];
  photoCount: number;
}

export interface MyYearShareManifest {
  version: 1;
  product: "myyear";
  year: number;
  title: string;
  momentCount: number;
  photoCount: number;
  activeMonths: string[];
  eras: Array<{ label: string; moments: number }>;
  attribution: true;
}

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function parseMomentDate(date: string) {
  const value = new Date(`${date}T12:00:00`);
  if (!Number.isFinite(value.getTime())) throw new Error("Every MyYear moment needs a valid date.");
  return value;
}

export function buildMyYearSummary(year: number, title: string, moments: MyYearMoment[]): MyYearSummary {
  if (!Number.isInteger(year) || year < 1900 || year > 2200) throw new Error("Choose a valid year.");
  const cleanedTitle = title.trim() || `My ${year}`;
  const sorted = moments
    .map((moment) => ({ ...moment, title: moment.title.trim(), caption: moment.caption?.trim(), location: moment.location?.trim() }))
    .filter((moment) => moment.title)
    .sort((a, b) => parseMomentDate(a.date).getTime() - parseMomentDate(b.date).getTime());

  for (const moment of sorted) {
    if (parseMomentDate(moment.date).getFullYear() !== year) throw new Error(`Moment “${moment.title}” is outside ${year}.`);
  }

  const counts = Array.from({ length: 12 }, (_, month) => ({ month, label: MONTHS[month], moments: 0 }));
  for (const moment of sorted) counts[parseMomentDate(moment.date).getMonth()].moments += 1;

  const eras: MyYearEra[] = [];
  let start: number | null = null;
  let total = 0;
  for (let month = 0; month < 12; month += 1) {
    const count = counts[month].moments;
    if (count > 0) {
      if (start === null) start = month;
      total += count;
    }
    const nextActive = month < 11 && counts[month + 1].moments > 0;
    if (start !== null && (!nextActive || month === 11)) {
      eras.push({
        id: `era-${eras.length + 1}`,
        label: start === month ? MONTHS[start] : `${MONTHS[start]}–${MONTHS[month]}`,
        startMonth: start,
        endMonth: month,
        moments: total,
      });
      start = null;
      total = 0;
    }
  }

  return {
    schemaVersion: 1,
    product: "myyear",
    year,
    title: cleanedTitle,
    moments: sorted,
    monthlyCounts: counts,
    eras,
    photoCount: sorted.reduce((sum, moment) => sum + Math.max(0, moment.photoCount), 0),
  };
}

export function myYearEvents(summary: MyYearSummary): StoryEvent[] {
  return summary.moments.map((moment) => ({
    id: moment.id,
    product: "myyear",
    occurredAt: `${moment.date}T12:00:00.000Z`,
    type: "memory",
    title: moment.title,
    description: moment.caption,
    location: moment.location,
    metadata: { photoCount: moment.photoCount },
  }));
}

export function composeMyYearChapters(summary: MyYearSummary): StoryChapter[] {
  const activeMonths = summary.monthlyCounts.filter((item) => item.moments > 0);
  const busiest = [...summary.monthlyCounts].sort((a, b) => b.moments - a.moments)[0];
  const chapters: StoryChapter[] = [
    { id: "myyear-cover", type: "cover", title: summary.title, subtitle: `${summary.year} · your year in moments`, privacyLevel: "safe", renderVariant: "hero" },
    { id: "myyear-scale", type: "scale", title: "A year worth keeping", metric: summary.moments.length, subtitle: `${summary.photoCount} selected photos · ${activeMonths.length} active months`, privacyLevel: "safe", renderVariant: "metric" },
  ];

  if (busiest?.moments) chapters.push({ id: "myyear-busiest", type: "timeline", title: `${busiest.label} held the most memories`, metric: busiest.moments, subtitle: "saved moments", privacyLevel: "safe", renderVariant: "metric" });
  if (summary.eras.length) chapters.push({ id: "myyear-eras", type: "timeline", title: "Your year moved in eras", metric: summary.eras.length, supportingText: summary.eras.map((era) => `${era.label} · ${era.moments}`).join("  •  "), privacyLevel: "safe", renderVariant: "timeline" });

  for (const moment of summary.moments.slice(0, 4)) {
    chapters.push({ id: `myyear-${moment.id}`, type: "beginning", title: moment.title, subtitle: new Intl.DateTimeFormat("en", { month: "long", day: "numeric" }).format(parseMomentDate(moment.date)), supportingText: moment.location || undefined, privacyLevel: "sensitive", renderVariant: "hero" });
  }

  chapters.push({ id: "myyear-closing", type: "closing", title: `${summary.year}, kept.`, subtitle: "The ordinary days count too.", privacyLevel: "safe", renderVariant: "closing" });
  return chapters;
}

export function createMyYearShareManifest(summary: MyYearSummary): MyYearShareManifest {
  return {
    version: 1,
    product: "myyear",
    year: summary.year,
    title: summary.title,
    momentCount: summary.moments.length,
    photoCount: summary.photoCount,
    activeMonths: summary.monthlyCounts.filter((item) => item.moments > 0).map((item) => item.label),
    eras: summary.eras.map(({ label, moments }) => ({ label, moments })),
    attribution: true,
  };
}

import type { StoryChapter, StoryEvent } from "@/platform/types";

export type PetMemoryType = "memory" | "milestone";

export interface PetProfile { id: string; name: string; species: string; birthday?: string; adoptionDate?: string; }
export interface PetMemory { id: string; petId: string; type: PetMemoryType; date: string; title: string; note?: string; photoCount: number; }
export interface PetLifeRecap { schemaVersion: 1; product: "petlife"; year: number; pet: PetProfile; memories: PetMemory[]; monthlyCounts: Array<{ month: number; label: string; memories: number }>; milestoneCount: number; photoCount: number; }
export interface PetLifeShareManifest { version: 1; product: "petlife"; year: number; petName?: string; memoryCount: number; milestoneCount: number; photoCount: number; activeMonths: string[]; attribution: true; }

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
function parseDate(value: string) { const date = new Date(`${value}T12:00:00`); if (!Number.isFinite(date.getTime())) throw new Error("Pet memories need a valid date."); return date; }

export function buildPetLifeRecap(profile: PetProfile, memories: PetMemory[], year: number): PetLifeRecap {
  if (!profile.name.trim() || !profile.species.trim()) throw new Error("Create a pet profile first.");
  if (!Number.isInteger(year) || year < 1900 || year > 2200) throw new Error("Choose a valid recap year.");
  const sorted = memories.filter((memory) => memory.petId === profile.id && parseDate(memory.date).getFullYear() === year).map((memory) => ({ ...memory, title: memory.title.trim(), note: memory.note?.trim() })).filter((memory) => memory.title).sort((a, b) => parseDate(a.date).getTime() - parseDate(b.date).getTime());
  const monthlyCounts = Array.from({ length: 12 }, (_, month) => ({ month, label: MONTHS[month], memories: 0 }));
  for (const memory of sorted) monthlyCounts[parseDate(memory.date).getMonth()].memories += 1;
  return { schemaVersion: 1, product: "petlife", year, pet: { ...profile, name: profile.name.trim(), species: profile.species.trim() }, memories: sorted, monthlyCounts, milestoneCount: sorted.filter((memory) => memory.type === "milestone").length, photoCount: sorted.reduce((sum, memory) => sum + Math.max(0, memory.photoCount), 0) };
}

export function petLifeEvents(recap: PetLifeRecap): StoryEvent[] {
  return recap.memories.map((memory) => ({ id: memory.id, product: "petlife", occurredAt: `${memory.date}T12:00:00.000Z`, type: memory.type, title: memory.title, description: memory.note, metadata: { photoCount: memory.photoCount, petId: memory.petId } }));
}

export function composePetLifeChapters(recap: PetLifeRecap): StoryChapter[] {
  const activeMonths = recap.monthlyCounts.filter((item) => item.memories > 0);
  const busiest = [...recap.monthlyCounts].sort((a, b) => b.memories - a.memories)[0];
  const chapters: StoryChapter[] = [
    { id: "pet-cover", type: "cover", title: `${recap.pet.name}'s ${recap.year}`, subtitle: `${recap.pet.species} · a year of memories`, privacyLevel: "safe", renderVariant: "hero" },
    { id: "pet-scale", type: "scale", title: "The moments you kept", metric: recap.memories.length, subtitle: `${recap.milestoneCount} milestones · ${recap.photoCount} selected photos`, privacyLevel: "safe", renderVariant: "metric" },
  ];
  if (busiest?.memories) chapters.push({ id: "pet-busiest", type: "timeline", title: `${busiest.label} was full of stories`, metric: busiest.memories, subtitle: "saved memories", privacyLevel: "safe", renderVariant: "metric" });
  for (const memory of recap.memories.slice(0, 5)) chapters.push({ id: `pet-${memory.id}`, type: memory.type === "milestone" ? "beginning" : "timeline", title: memory.title, subtitle: new Intl.DateTimeFormat("en", { month: "long", day: "numeric" }).format(parseDate(memory.date)), supportingText: memory.note || undefined, privacyLevel: "sensitive", renderVariant: "hero" });
  chapters.push({ id: "pet-closing", type: "closing", title: `${recap.pet.name}'s story keeps growing.`, subtitle: `${activeMonths.length} active months in ${recap.year}`, privacyLevel: "safe", renderVariant: "closing" });
  return chapters;
}

export function composePetLifeMemorialChapters(recap: PetLifeRecap): StoryChapter[] {
  return composePetLifeChapters(recap).map((chapter) => {
    if (chapter.id === "pet-cover") return { ...chapter, title: `Remembering ${recap.pet.name}`, subtitle: `${recap.pet.species} · a memory timeline you chose to revisit` };
    if (chapter.id === "pet-closing") return { ...chapter, title: "A story worth keeping.", subtitle: `${recap.memories.length} memories selected from ${recap.year}`, supportingText: "Memorial mode changes presentation only. It does not infer anything from the timeline." };
    return chapter;
  });
}

export function createPetLifeShareManifest(recap: PetLifeRecap, includePetName = false): PetLifeShareManifest {
  return { version: 1, product: "petlife", year: recap.year, ...(includePetName ? { petName: recap.pet.name } : {}), memoryCount: recap.memories.length, milestoneCount: recap.milestoneCount, photoCount: recap.photoCount, activeMonths: recap.monthlyCounts.filter((item) => item.memories > 0).map((item) => item.label), attribution: true };
}

